parameters.jsCode:
const inputData = $input.first()?.json || {};
const body = inputData.body || inputData;

// 1. Resolve Multi-Environment URLs & Secrets (Render Live & Local Dev)
// Priority: 1. Body payload from Sutra App | 2. n8n Variables ($vars) | 3. Render Environment ($env)
const sutraBaseUrl = body.appBaseUrl || (typeof $vars !== 'undefined' && $vars.SUTRA_STUDIO_URL) || $env.SUTRA_STUDIO_URL || $env.APP_BASE_URL || 'https://sutrastudios.in';
const sutraSecret = body.sutraSecret || (typeof $vars !== 'undefined' && $vars.N8N_WEBHOOK_SECRET) || $env.N8N_WEBHOOK_SECRET || '';
const geminiApiKey = body.geminiApiKey || (typeof $vars !== 'undefined' && $vars.GEMINI_API_KEY) || $env.GEMINI_API_KEY || $env.GOOGLE_AI_API_KEY || '';
const openrouterApiKey = body.openrouterApiKey || (typeof $vars !== 'undefined' && $vars.OPENROUTER_API_KEY) || $env.OPENROUTER_API_KEY || '';

// 2. Determine Mode
// Mode A: agency_self_promo -> Sutra Studio Meta Promotion (4K Images, Commercial Video Reels, 3D Models, 360 Virtual Tours)
// Mode B: client_order_fulfillment -> Client Package Delivery (Starter/Growth Trend, Daily Creator, Logo, 3D, 360, Retainers)
let mode = 'client_order_fulfillment';
if (
  body.mode === 'agency_self_promo' ||
  body.isStudioSelfMarketing ||
  body.campaignName ||
  !body.orderId ||
  inputData.triggerSource === 'scheduleTrigger'
) {
  mode = 'agency_self_promo';
}

// 3. Disciplines for Studio Promotion
const DISCIPLINES = [
  {
    id: 'visuals-motion',
    name: '4K Commercial Video Reels',
    topic: 'Why Luxury Brands are Replacing Physical Shoots with 4K CGI Reels',
    sampleVideo: '/videos/services/ai-video-mobile.mp4'
  },
  {
    id: '3d-modeling',
    name: '3D CAD Modeling & Turntable CGI',
    topic: 'Haute Horology & Jewelry: Hyper-Realistic 3D Product Animations with Micro-Facet Reflections',
    sampleVideo: '/videos/services/spatial-3d-mobile.mp4'
  },
  {
    id: '360-view',
    name: '360° Virtual Space Walkthroughs',
    topic: 'Architectural Pre-Sales: Selling Luxury Villas Before Groundbreak with Interactive 360 Walkthroughs',
    sampleVideo: '/videos/services/spatial-3d-mobile.mp4'
  },
  {
    id: 'interior-design',
    name: 'Architectural & Interior CGI',
    topic: 'Photorealistic Daylight Simulation and Material Luxury in High-End Villa Design',
    sampleVideo: '/videos/studio/studio-reel-mobile.mp4'
  },
  {
    id: 'brand-identity',
    name: 'Vedic-Modern Brand Identity Suites',
    topic: 'Golden Ratio Sacred Geometry & Bilingual Typography in High-Converting Luxury Branding',
    sampleVideo: '/videos/studio/studio-reel-mobile.mp4'
  },
  {
    id: 'digital-marketing-ads',
    name: 'High-ROAS Meta Ad Creatives',
    topic: 'The 3-Second Visual Hook Formula: Stopping the Scroll on Instagram Reels',
    sampleVideo: '/videos/services/ai-video-mobile.mp4'
  }
];

const selectedDiscipline = DISCIPLINES.find(d => d.id === body.disciplineId) || DISCIPLINES[Math.floor(Math.random() * DISCIPLINES.length)];

const runId = body.runId || `sutra_master_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
const now = new Date().toISOString();

return [{
  json: {
    mode,
    runId,
    timestamp: now,
    sutraBaseUrl,
    sutraSecret,
    geminiApiKey,
    openrouterApiKey,
    orderId: body.orderId || `PROMO-${Date.now().toString().slice(-6)}`,
    packageId: body.packageId || body.serviceDetails?.packageId || (body.orderAmount >= 19999 ? 'daily-trend-creator' : 'starter-trend'),
    service: body.service || body.serviceDetails?.service || selectedDiscipline.name,
    brief: body.brief || 'Luxury commercial showcase with warm ivory and polished brass accents.',
    client: {
      name: body.client?.name || 'Sutra Client',
      email: body.client?.email || 'client@sutrastudio.com',
      brandName: body.client?.brandName || 'Sutra Luxe'
    },
    selfPromoDiscipline: selectedDiscipline,
    isStudioSelfMarketing: mode === 'agency_self_promo'
  }
}];

