const base = $('Mode Detector & Normalizer').first()?.json || {};
const rawGemini = $input.first()?.json || {};
let parsed = {};

try {
  const rawText = rawGemini?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawText) {
    const jsonStart = rawText.indexOf('{');
    const jsonEnd = rawText.lastIndexOf('}');
    if (jsonStart !== -1 && jsonEnd !== -1) {
      parsed = JSON.parse(rawText.substring(jsonStart, jsonEnd + 1));
    } else {
      parsed = JSON.parse(rawText);
    }
  }
} catch (e) {
  parsed = {};
}

// Safe fallbacks adhering strictly to Sutra Studio standards
if (!parsed.topic) parsed.topic = base.selfPromoDiscipline?.topic || '4K Commercial Reels vs Physical Shoots';
if (!parsed.headline) parsed.headline = 'Sutra Studio • 4K Commercial Reels & 3D CGI Engine';
if (!parsed.hook) parsed.hook = 'Stop spending ₹5 Lakhs on camera crews for your product videos.';
