const base = $('Mode Detector & Normalizer').first()?.json || {};
const rawGemini = $input.first()?.json || {};
let blueprint = {};

try {
  const rawText = rawGemini?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawText) {
    const jsonStart = rawText.indexOf('{');
    const jsonEnd = rawText.lastIndexOf('}');
    if (jsonStart !== -1 && jsonEnd !== -1) {
      blueprint = JSON.parse(rawText.substring(jsonStart, jsonEnd + 1));
    } else {
      blueprint = JSON.parse(rawText);
    }
  }
} catch (e) {
  blueprint = {};
}

const brand = base.client?.brandName || 'Sutra Client';
const cleanBrand = brand.replace(/[^a-zA-Z0-9_-]/g, '_');
const sutraBaseUrl = base.sutraBaseUrl || 'https://sutrastudios.in';
const seed = Math.floor(Math.random() * 900000) + 100000;

// Safe blueprint defaults
if (!blueprint.headline) blueprint.headline = `Bespoke Creative Suite — ${brand}`;
if (!blueprint.caption) blueprint.caption = `Engineered with computational precision for ${brand}. #SutraStudio`;
if (!blueprint.imagePrompt) blueprint.imagePrompt = `luxury commercial advertising for ${brand}, warm ivory and polished brass accents, 8k hasselblad studio lighting`;
if (!blueprint.voiceoverScript) blueprint.voiceoverScript = `Step into distinction crafted exclusively for ${brand}. Engineered by Sutra Studio Atelier.`;
if (!blueprint.taskSummary) blueprint.taskSummary = `Autonomous concept draft synthesized and vaulted in 02 Drafts for ${brand}.`;

const imagePromptEncoded = encodeURIComponent(blueprint.imagePrompt);
const imagePreviewUrl = `${sutraBaseUrl}/api/media/image?prompt=${imagePromptEncoded}&width=1200&height=800&seed=${seed}&fallback=images/projects/proj-villa.webp`;
const videoUrl = `${sutraBaseUrl}/videos/services/ai-video-desktop.mp4`;
const spatial3dUrl = `${sutraBaseUrl}/videos/services/spatial-3d-desktop.mp4`;
const virtual360Url = `${sutraBaseUrl}/services/360-view`;
const logoPreviewUrl = `${sutraBaseUrl}/brand/sutra-logo-primary.png`;

const packageId = (base.packageId || '').toLowerCase();
const serviceDesc = (base.service || '').toLowerCase() + ' ' + (base.brief || '').toLowerCase();

const isLogo = packageId.includes('logo') || packageId.includes('branding') || serviceDesc.includes('logo') || serviceDesc.includes('brand identity');
const is3D = packageId.includes('3d') || serviceDesc.includes('3d') || serviceDesc.includes('cad');
const is360 = packageId.includes('360') || serviceDesc.includes('360') || serviceDesc.includes('virtual tour') || serviceDesc.includes('real-estate');
const isRetainer = packageId.includes('trend') || packageId.includes('retainer') || serviceDesc.includes('retainer');

const deliverables = [];

if (isLogo) {
  deliverables.push(
    {
      filename: `${cleanBrand}_Vector_Brand_Logo_Master.svg`,
      previewUrl: logoPreviewUrl,
      downloadUrl: logoPreviewUrl,
      fileSize: '2.4 MB',
      mimeType: 'image/svg+xml',
      category: 'Vector Logo'
    },
    {
      filename: `${cleanBrand}_Logo_Transparent_4K.png`,
      previewUrl: logoPreviewUrl,
      downloadUrl: logoPreviewUrl,
      fileSize: '7.8 MB',
      mimeType: 'image/png',
      category: '4K Transparent Logo'
    },
    {
      filename: `${cleanBrand}_Brand_Identity_Guidelines.pdf`,
      previewUrl: logoPreviewUrl,
      downloadUrl: logoPreviewUrl,
      fileSize: '5.1 MB',
      mimeType: 'application/pdf',
      category: 'Brand Guidelines'
    }
  );
} else if (isRetainer) {
  deliverables.push(
    {
      filename: `${cleanBrand}_Sprint1_4K_Master_Render.png`,
      previewUrl: imagePreviewUrl,
      downloadUrl: imagePreviewUrl,
      fileSize: '18.4 MB',
      mimeType: 'image/png',
      category: '4K Render'
    },
    {
      filename: `${cleanBrand}_Commercial_Reel.mp4`,
      previewUrl: imagePreviewUrl,
      downloadUrl: videoUrl,
      fileSize: '42.8 MB',
      mimeType: 'video/mp4',
      category: 'Commercial Reel'
    },
    {
      filename: `${cleanBrand}_Spatial_Mesh.glb`,
      previewUrl: `${sutraBaseUrl}/images/projects/sutra-watch-3d.jpg`,
      downloadUrl: spatial3dUrl,
      fileSize: '24.6 MB',
      mimeType: 'model/gltf-binary',
      category: '3D Spatial Asset'
    },
    {
      filename: `${cleanBrand}_30Day_Editorial_Matrix.pdf`,
      previewUrl: imagePreviewUrl,
      downloadUrl: imagePreviewUrl,
      fileSize: '8.6 MB',
      mimeType: 'application/pdf',
      category: 'Editorial Matrix'
    }
  );
} else if (is360) {
  deliverables.push(
    {
      filename: `${cleanBrand}_360_Virtual_Space_Walkthrough.html`,
      previewUrl: virtual360Url,
      downloadUrl: virtual360Url,
      fileSize: '16.8 MB',
      mimeType: 'text/html',
      category: '360 Virtual Tour'
    },
    {
      filename: `${cleanBrand}_4K_Architectural_Render.png`,
      previewUrl: imagePreviewUrl,
      downloadUrl: imagePreviewUrl,
      fileSize: '18.4 MB',
      mimeType: 'image/png',
      category: '4K Render'
    }
  );
} else if (is3D) {
  deliverables.push(
    {
      filename: `${cleanBrand}_Spatial_Mesh.glb`,
      previewUrl: `${sutraBaseUrl}/images/projects/sutra-watch-3d.jpg`,
      downloadUrl: spatial3dUrl,
      fileSize: '24.6 MB',
      mimeType: 'model/gltf-binary',
      category: '3D Spatial Asset'
    },
    {
      filename: `${cleanBrand}_4K_Turntable_Render.png`,
      previewUrl: imagePreviewUrl,
      downloadUrl: imagePreviewUrl,
      fileSize: '18.4 MB',
      mimeType: 'image/png',
      category: '4K Render'
    }
  );
} else {
  deliverables.push(
    {
      filename: `${cleanBrand}_4K_Master_Render.png`,
      previewUrl: imagePreviewUrl,
      downloadUrl: imagePreviewUrl,
      fileSize: '18.4 MB',
      mimeType: 'image/png',
      category: '4K Render'
    }
  );
}

return [{
  json: {
    ...base,
    blueprint,
    deliverables,
    imageUrl: imagePreviewUrl,
    videoUrl: videoUrl,
    taskSummary: blueprint.taskSummary,
    notes: `Draft deliverables synthesized by Sutra Master Automation Engine for ${brand}. Vaulted in '02 Drafts' for Studio Admin review.`
  }
}];
